from google.cloud import vision
import os

class VisionClient:
    def __init__(self):
        self._client = vision.ImageAnnotatorClient()

    def get_client(self):
        return self._client

from google.cloud import vision

def create_image_from_bytes(image_bytes):
    return vision.Image(content=image_bytes)

def create_feature(feature_type, max_results=None):
    feature = vision.Feature(type=feature_type)
    if max_results:
        feature.max_results = max_results
    return feature

def parse_label_detection_response(response):
    labels = []
    if response.label_annotations:
        for label in response.label_annotations:
            labels.append({'name': label.description, 'confidence': label.score})
    return labels

def parse_text_detection_response(response):
    texts = []
    if response.text_annotations:
        for text in response.text_annotations:
            texts.append({'text': text.description, 'confidence': text.score if hasattr(text, 'score') else None})
    return texts

def parse_safe_search_detection_response(response):
    safe_search_annotation = response.safe_search_annotation
    if safe_search_annotation:
        return {
            'adult': safe_search_annotation.adult.name,
            'spoof': safe_search_annotation.spoof.name,
            'medical': safe_search_annotation.medical.name,
            'violence': safe_search_annotation.violence.name,
            'racy': safe_search_annotation.racy.name,
        }
    return {}

def parse_web_detection_response(response):
    web_detection = response.web_detection
    web_entities = []
    if web_detection and web_detection.web_entities:
        for entity in web_detection.web_entities:
            web_entities.append({'description': entity.description, 'score': entity.score})
    return web_entities

import boto3
import os

def detect_image_text(payload, config=None):
    config = config or {}
    rekognition_client = boto3.client(
        'rekognition',
        region_name=config.get('aws_region', os.environ.get('AWS_REGION')),
        aws_access_key_id=config.get('aws_access_key_id', os.environ.get('AWS_ACCESS_KEY_ID')),
        aws_secret_access_key=config.get('aws_secret_access_key', os.environ.get('AWS_SECRET_ACCESS_KEY'))
    )

    response = rekognition_client.detect_text(Image={'Bytes': payload['image_bytes']})

    detected_text = []
    for text_detection in response['TextDetections']:
        if text_detection['Type'] == 'WORD':
            detected_text.append({
                'text': text_detection['DetectedText'],
                'confidence': text_detection['Confidence']
            })

    return {'detected_text': detected_text}

from clarifai.client.workflow import Workflow
import os

def score_image_safety(payload, config=None):
    config = config or {}
    # You need to set your CLARIFAI_PAT (Personal Access Token) as an environment variable.
    # For example: export CLARIFAI_PAT='YOUR_CLARIFAI_PAT_HERE'
    workflow_url = config.get('clarifai_workflow_url', "https://clarifai.com/clarifai/main/workflows/moderation-workflow")

    workflow = Workflow(workflow_url)

    # The predict method takes a list of inputs. For image bytes, you can pass them directly.
    # The input type is automatically detected by the Clarifai SDK.
    prediction_response = workflow.predict_by_bytes(
        image_bytes=payload['image_bytes'], 
        input_type="image"
    )

    # Parse the prediction response to extract safety scores
    safety_scores = {}
    if prediction_response.results:
        for concept in prediction_response.results[0].outputs[0].data.concepts:
            safety_scores[concept.name] = concept.value

    return {'safety_scores': safety_scores}

from openai import OpenAI
import os

def image_summary(payload, config=None):
    config = config or {}
    client = OpenAI(api_key=config.get('openai_api_key', os.environ.get('OPENAI_API_KEY')))

    # Combine all visual analysis results into a single string for summarization
    analysis_results = []
    if 'labels' in payload and payload['labels']:
        analysis_results.append(f"Detected labels: {', '.join([label['name'] for label in payload['labels']])}.")
    if 'description' in payload and payload['description']:
        analysis_results.append(f"Image description: {payload['description']}")
    if 'detected_text' in payload and payload['detected_text']:
        text_content = " ".join([text['text'] for text in payload['detected_text']])
        analysis_results.append(f"Detected text: \"{text_content}\".")
    if 'safe_search_results' in payload and payload['safe_search_results']:
        safety_info = ", ".join([f'{k}: {v}' for k, v in payload['safe_search_results'].items()])
        analysis_results.append(f"Safety analysis: {safety_info}.")
    if 'safety_scores' in payload and payload['safety_scores']:
        clarifai_safety_info = ", ".join([f'{k}: {v:.2f}' for k, v in payload['safety_scores'].items()])
        analysis_results.append(f"Clarifai safety scores: {clarifai_safety_info}.")

    full_analysis_text = " ".join(analysis_results).strip()

    if not full_analysis_text:
        return {'summary': "No visual analysis results provided to summarize."}

    prompt = f"Summarize the following visual analysis results concisely: {full_analysis_text}"

    response = client.chat.completions.create(
        model=config.get('openai_model', "gpt-4"),
        messages=[
            {"role": "system", "content": "You are a helpful assistant that summarizes image analysis results."},
            {"role": "user", "content": prompt}
        ]
    )

    summary = response.choices[0].message.content.strip()
    return {'summary': summary}

from google.cloud import translate_v2 as translate
import os

def alt_text_translate(payload, config=None):
    config = config or {}
    translate_client = translate.Client()

    text_to_translate = payload.get('text', '')
    target_language = config.get('target_language', 'es') # Default to Spanish

    if not text_to_translate:
        return {'translated_text': ''}

    result = translate_client.translate(text_to_translate, target_language=target_language)

    return {'translated_text': result['translatedText']}

from openai import OpenAI
import os

def visual_safety_text(payload, config=None):
    config = config or {}
    client = OpenAI(api_key=config.get('openai_api_key', os.environ.get('OPENAI_API_KEY')))

    text_to_moderate = payload.get('text', '')

    if not text_to_moderate:
        return {'moderation_result': {'flagged': False, 'categories': {}}}

    response = client.moderations.create(input=text_to_moderate)

    moderation_result = response.results[0]

    return {
        'moderation_result': {
            'flagged': moderation_result.flagged,
            'categories': {
                cat.name: cat.score for cat in moderation_result.categories
            }
        }
    }
